// OSM road classes for the live GSI builder, from VersaTiles' public OSM vector tiles (Shortbread schema, CORS-enabled).
// GSI rdCtg=1 (prefectural) cannot tell 主要地方道 (main) from 一般県道 (ordinary); OSM primary/secondary does
// (99.5% length-weighted on census sections, research-traffic.md). street_labels carry national route refs (trunk).
import Pbf from '../../vendor/pbf.mjs';
import { VectorTile } from '../../vendor/vector-tile.mjs';
import { bikeWayType } from '../bike-infra.mjs';

// What OSM says a way is, for tagging the GSI links that lie on it (wayVote below): an ordinary road, a track that is
// neither grade1 nor paved, a path with no bike tag and no paved surface, or a bike way (cycleway, or a path / footway
// / track where bikes are allowed); WAY_UNPAVED is added where the surface is unpaved (a track or path without a
// surface tag counts as unpaved, as in the 'osm' source). -1: not a road (rail, tram, runways).
export const WAY_ROAD = 0, WAY_TRACK = 1, WAY_PATH = 2, WAY_BIKE = 3, WAY_UNPAVED = 4;
export const OSM_UNPAVED = /^(unpaved|gravel|fine_gravel|compacted|dirt|earth|ground|grass|sand|mud|pebblestone|rock|woodchips)$/;
const WAY_KINDS = /^(motorway|trunk|primary|secondary|tertiary|unclassified|residential|living_street|service|track|cycleway|path|footway|pedestrian|bridleway|steps)$/;
export function osmWayTag(p) {
  const kind = String(p.kind ?? '');
  if (!WAY_KINDS.test(kind)) return -1;
  const paved = p.surface != null ? !OSM_UNPAVED.test(p.surface) : null; // null: no surface tag
  if (bikeWayType(p)) return WAY_BIKE | (paved === false ? WAY_UNPAVED : 0);
  if (kind === 'track') return p.tracktype === 'grade1' || paved ? WAY_ROAD : WAY_TRACK | WAY_UNPAVED;
  if (kind === 'path') return paved ? WAY_ROAD : WAY_PATH | WAY_UNPAVED;
  return paved === false ? WAY_UNPAVED : WAY_ROAD;
}
// Every road segment of the tiles with its tag, in typed arrays (a big corridor has millions)
export class WaySegs {
  constructor() { this.n = 0; this.xy = new Float32Array(1 << 14); this.tag = new Uint8Array(1 << 12); }
  push(ax, ay, bx, by, tag) {
    if (this.n === this.tag.length) { const xy = new Float32Array(8 * this.n), tag = new Uint8Array(2 * this.n); xy.set(this.xy); tag.set(this.tag); this.xy = xy; this.tag = tag; }
    const xy = this.xy, o = 4 * this.n; xy[o] = ax; xy[o + 1] = ay; xy[o + 2] = bx; xy[o + 3] = by; this.tag[this.n++] = tag;
  }
}

// segments in local metres: { a:[x,y], b:[x,y], kind, ref }. If bikeLines is given, bike facilities in the streets
// layer (kind=cycleway, or path/footway/... with bicycle=yes) are appended to it as polylines in local metres.
// If ways (a WaySegs) is given, every road of the streets layer goes into it with its osmWayTag.
export function decodeOsmStreets(tiles, buffers, toLocal, bikeLines = null, ways = null) {
  const segs = [];
  tiles.forEach((t, k) => {
    const buf = buffers[k]; if (!buf || !buf.length) return;
    const vt = new VectorTile(new Pbf(buf));
    for (const [layer, isLabel] of [['streets', false], ['street_labels', true]]) {
      const L = vt.layers[layer]; if (!L) continue;
      const E = L.extent, n = 2 ** t.z;
      for (let i = 0; i < L.length; i++) {
        const f = L.feature(i); if (f.type !== 2) continue;
        const p = f.properties, kind = String(p.kind ?? '');
        const bt = bikeLines && !isLabel ? bikeWayType(p) : 0, wt = ways && !isLabel ? osmWayTag(p) : -1;
        const vote = !bt && /^(trunk|primary|secondary)$/.test(kind) && !(isLabel && !p.ref);
        if (!bt && !vote && wt < 0) continue;
        const ref = isLabel ? String(p.ref) : null;
        // bikeLines = { sep, shared }: dedicated cycleways vs shared sidewalks/paths (自転車歩行者道)
        const target = bt === 2 ? bikeLines.sep : bt ? bikeLines.shared : null;
        for (const line of f.loadGeometry()) {
          const pts = line.map(({ x, y }) => toLocal([((t.x + x / E) / n) * 360 - 180,
            (180 / Math.PI) * Math.atan(Math.sinh(Math.PI - (2 * Math.PI * (t.y + y / E)) / n))]));
          if (target) target.push(pts);
          for (let k = 1; k < pts.length; k++) {
            if (vote) segs.push({ a: pts[k - 1], b: pts[k], kind, ref });
            if (wt >= 0) ways.push(pts[k - 1][0], pts[k - 1][1], pts[k][0], pts[k][1], wt);
          }
        }
      }
    }
  });
  return segs;
}

// grid index over segments; nearest(x, y, ang, maxD, filter) -> segment or null (parallel within 30°)
export function segmentIndex(segs, cell = 50) {
  const grid = new Map();
  segs.forEach((s, i) => {
    const x0 = Math.floor(Math.min(s.a[0], s.b[0]) / cell), x1 = Math.floor(Math.max(s.a[0], s.b[0]) / cell);
    const y0 = Math.floor(Math.min(s.a[1], s.b[1]) / cell), y1 = Math.floor(Math.max(s.a[1], s.b[1]) / cell);
    for (let gx = x0; gx <= x1; gx++) for (let gy = y0; gy <= y1; gy++) { const k = gx * 1e6 + gy; (grid.get(k) ?? grid.set(k, []).get(k)).push(i); }
  });
  const angDiff = (a, b) => { const d = Math.abs(a - b) % Math.PI; return Math.min(d, Math.PI - d); };
  return function nearest(x, y, ang, maxD, filter = () => true) {
    let best = null, bd = maxD;
    const gx = Math.floor(x / cell), gy = Math.floor(y / cell), r = Math.ceil(maxD / cell);
    for (let a = -r; a <= r; a++) for (let b = -r; b <= r; b++) for (const i of grid.get((gx + a) * 1e6 + gy + b) ?? []) {
      const s = segs[i]; if (!filter(s)) continue;
      const dx = s.b[0] - s.a[0], dy = s.b[1] - s.a[1], l2 = dx * dx + dy * dy;
      if (ang != null && l2 > 1 && angDiff(Math.atan2(dy, dx), ang) > Math.PI / 6) continue;
      const u = l2 ? Math.max(0, Math.min(1, ((x - s.a[0]) * dx + (y - s.a[1]) * dy) / l2)) : 0;
      const d = Math.hypot(s.a[0] + u * dx - x, s.a[1] + u * dy - y);
      if (d < bd) { bd = d; best = s; }
    }
    return best;
  };
}

// vote along a polyline (local metres): main vs ordinary prefectural (length), and the national route number
export function voteLink(coords, nearest, maxD = 15) {
  const vote = { main: 0, ord: 0 }, nums = new Map();
  for (let i = 1; i < coords.length; i++) {
    const [ax, ay] = coords[i - 1], [bx, by] = coords[i], L = Math.hypot(bx - ax, by - ay); if (!(L > 0)) continue;
    const ang = Math.atan2(by - ay, bx - ax);
    for (let d = Math.min(10, L / 2); d < L; d += 20) {
      const x = ax + ((bx - ax) * d) / L, y = ay + ((by - ay) * d) / L, w = Math.min(20, L);
      const s = nearest(x, y, ang, maxD, (q) => !q.ref);
      if (s?.kind === 'primary') vote.main += w; else if (s?.kind === 'secondary') vote.ord += w;
      const r = nearest(x, y, ang, maxD, (q) => q.ref && q.kind === 'trunk');
      if (r) for (const m of r.ref.split(/[;,]/)) { const n = parseInt(m, 10); if (n > 0) nums.set(n, (nums.get(n) ?? 0) + w); }
    }
  }
  const routeNo = nums.size ? [...nums].sort((a, b) => b[1] - a[1])[0][0] : 0;
  return { main: vote.main, ord: vote.ord, routeNo };
}

// Grid over the way segments (cells of `cell` metres inside the box [x0, y0, x1, y1], local metres).
// at(x, y, ux, uy) -> the tag of the nearest way within maxD that runs within 45 degrees of the unit direction
// (ux, uy), or -1 when OSM has no such way there.
export function wayIndex(ways, [x0, y0, x1, y1], cell = 50, maxD = 20) {
  const gw = Math.ceil((x1 - x0) / cell) + 1, gh = Math.ceil((y1 - y0) / cell) + 1, xy = ways.xy, start = new Int32Array(gw * gh + 1);
  const cells = (s, fn) => {
    const i0 = Math.floor((Math.min(xy[4 * s], xy[4 * s + 2]) - x0) / cell), i1 = Math.floor((Math.max(xy[4 * s], xy[4 * s + 2]) - x0) / cell);
    const j0 = Math.floor((Math.min(xy[4 * s + 1], xy[4 * s + 3]) - y0) / cell), j1 = Math.floor((Math.max(xy[4 * s + 1], xy[4 * s + 3]) - y0) / cell);
    for (let j = Math.max(0, j0); j <= Math.min(gh - 1, j1); j++) for (let i = Math.max(0, i0); i <= Math.min(gw - 1, i1); i++) fn(j * gw + i);
  };
  for (let s = 0; s < ways.n; s++) cells(s, (c) => { start[c + 1]++; });
  for (let c = 0; c < gw * gh; c++) start[c + 1] += start[c];
  const list = new Int32Array(start[gw * gh]), fill = start.slice(0, gw * gh);
  for (let s = 0; s < ways.n; s++) cells(s, (c) => { list[fill[c]++] = s; });
  return function at(x, y, ux, uy) {
    const gi = Math.floor((x - x0) / cell), gj = Math.floor((y - y0) / cell);
    let best = -1, bd = maxD;
    for (let j = Math.max(0, gj - 1); j <= Math.min(gh - 1, gj + 1); j++) for (let i = Math.max(0, gi - 1); i <= Math.min(gw - 1, gi + 1); i++) {
      for (let q = start[j * gw + i]; q < start[j * gw + i + 1]; q++) {
        const s = 4 * list[q], ax = xy[s], ay = xy[s + 1], dx = xy[s + 2] - ax, dy = xy[s + 3] - ay, l2 = dx * dx + dy * dy;
        if (l2 < 1 || Math.abs(dx * ux + dy * uy) < 0.7 * Math.sqrt(l2)) continue;
        const u = Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / l2)), d = Math.hypot(ax + u * dx - x, ay + u * dy - y);
        if (d < bd) { bd = d; best = list[q]; }
      }
    }
    return best < 0 ? -1 : ways.tag[best];
  };
}

// What OSM says along a link (vertices s .. e-1 of X, Y, local metres), sampled every 20 m: metres of the link that
// lie on a track, a path, a bike way and an unpaved way, and the metres sampled (len).
export function wayVote(X, Y, s, e, at) {
  const v = { len: 0, track: 0, path: 0, bike: 0, unpaved: 0 };
  for (let i = s + 1; i < e; i++) {
    const ax = X[i - 1], ay = Y[i - 1], dx = X[i] - ax, dy = Y[i] - ay, L = Math.hypot(dx, dy); if (!(L > 0)) continue;
    const k = Math.max(1, Math.round(L / 20)), w = L / k;
    for (let q = 0; q < k; q++) {
      const f = (q + 0.5) / k, tag = at(ax + f * dx, ay + f * dy, dx / L, dy / L);
      v.len += w; if (tag < 0) continue;
      const kind = tag & 3;
      if (kind === WAY_TRACK) v.track += w; else if (kind === WAY_PATH) v.path += w; else if (kind === WAY_BIKE) v.bike += w;
      if (tag & WAY_UNPAVED) v.unpaved += w;
    }
  }
  return v;
}
