// Module Web Worker: builds the live road graph for a route or a rectangle.
//   (message protocol below, at self.onmessage)
// Tiles are kept in Cache Storage for 30 days, one cache per source ('gsi-tiles-v1', 'osm-tiles-v1'): tile-cache.mjs.
import { buildLiveGraph, graphBuffers } from './build-core.mjs';
import { TILE_CACHES, cachedTile } from './tile-cache.mjs';

const cachePromise = {};
const openCache = (source) => (cachePromise[source] ??= (self.caches ? caches.open(TILE_CACHES[source]).catch(() => null) : Promise.resolve(null)));
const fetchTile = async (source, url) => cachedTile(await openCache(source), url);

async function decodePng(bytes) {
  const bmp = await createImageBitmap(new Blob([bytes], { type: 'image/png' }), { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
  const cv = new OffscreenCanvas(bmp.width, bmp.height);
  const ctx = cv.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(bmp, 0, 0);
  bmp.close();
  return ctx.getImageData(0, 0, cv.width, cv.height).data;
}

// Protocol:
//   in:  { id, route, bufM, lod?, source?, area? }   build (lod: false = full detail, or { budgetKm, minInnerM }
//                                             overrides; source: 'gsi' (default) | 'osm'; area: [west, south, east,
//                                             north] builds that box, and route / bufM are then ignored)
//        { type: 'cancel', id }               stop build `id` at the next tile/stage boundary
//   out: { id, type: 'progress', stage, done?, total? }   stages: fetch, decode, dem, grade, noding, typed, traffic
//        { id, type: 'done', graph, hazards, stats }      stats.lod = { innerM, outer, reason, keptKm, totalKm, culledKm, overBudget? }
//        { id, type: 'cancelled' } | { id, type: 'error', message }
const cancelled = new Set();
self.onmessage = async (ev) => {
  const msg = ev.data;
  if (msg?.type === 'cancel') { cancelled.add(msg.id); return; }
  const { id, route, bufM, lod, source = 'gsi', area = null } = msg;
  try {
    const { graph, hazards, stats } = await buildLiveGraph(route, bufM, { fetchTile: (url) => fetchTile(source, url), decodePng }, {
      onProgress: (p) => self.postMessage({ id, type: 'progress', ...p }),
      isCancelled: () => cancelled.has(id),
      source, area,
      ...(lod !== undefined ? { lod } : {}),
    });
    self.postMessage({ id, type: 'done', graph, hazards, stats }, graphBuffers(graph));
  } catch (e) {
    if (e?.name === 'Cancelled') self.postMessage({ id, type: 'cancelled' });
    else self.postMessage({ id, type: 'error', message: e?.message ?? String(e) });
  } finally {
    cancelled.delete(id);
  }
};
